; Auto-generated by scripts/generate-palette-transitions.js from palettes/.
; Do not edit by hand -- regenerate instead.
;
; Every palette has one fixed IIgs slot layout: the IIgs palette 0 slot that each of the 32 NES
; palette RAM entries ($3F00-$3F1F) is shown in.  The layouts are chosen together, so that the
; background groups that keep the same slots across the transitions don't need their tiles
; redrawn (a group whose slots change has to be recompiled with the new swizzle table).
;
; Requires: NES_ColorToIIgs_X, NES_SetPaletteMap, RefreshPPUAttributesL, PPU_SetPaletteWritesL,
;           ppuPalDirty, _ppumask, PPU_MEM, SHR_PALETTES

; Swizzle tables, in the PALDATA segment (palettes.s)
PAL_TITLE_SWIZZLE EXT
PAL_DUCK_SWIZZLE EXT
PAL_CLAY_SWIZZLE EXT
PAL_FLASH_BG_SWIZZLE EXT
PAL_FLASH_SP_SWIZZLE EXT

; The palette ids (PAL_*) and pinned slots (PAL_SLOT_*) are in pal_defs.s.

; Layouts (NES color -> [slots] per group; *reserved, ~shown as):
;   title
;     BG0 $0F $2C $27 $0F -> [0,1,2,3]
;     BG1 $0F $0F $30 $30 -> [0,4,5,6]
;     BG2 $0F $0F $2A $2A -> [0,7,8,9]
;     BG3 $0F $0F $27 $27 -> [0,7,10,11]
;     SP0 $0F $0F $0F $0F -> [0,0,0,0]
;     SP1 $0F $0F $0F $0F -> [0,0,0,0]
;     SP2 $0F $0F $0F $0F -> [0,0,0,0]
;     SP3 $0F $0F $0F $0F -> [0,0,0,0]
;   duck
;     BG0 $21 $07 $29 $0A -> [0,9,8,1]
;     BG1 $21 $30 $29 $0A -> [0,10,8,1]
;     BG2 $21 $0F $29 $18~$07 -> [0,7,8,9]
;     BG3 $21 $0F $30 $16 -> [0,7,10,11]
;     SP0 $21 $30 *$0A *$0F -> [0,10,2,3]
;     SP1 $21 $30 $26 *$0F -> [0,10,4,5]
;     SP2 $21 $30 *$17 *$0F -> [0,10,6,12]
;     SP3 $21 *$07 *$17 *$0F -> [0,13,14,15]
;   clay
;     BG0 $2C $29 $19 $09 -> [0,1,2,3]
;     BG1 $2C $07 $29 $1A -> [0,4,5,6]
;     BG2 $2C $0F $29 $10 -> [0,7,8,9]
;     BG3 $2C $0F $30 $16 -> [0,7,10,11]
;     SP0 $2C $30 $0F $0F -> [0,10,7,7]
;     SP1 $2C $30 $16 $07 -> [0,10,11,4]
;     SP2 $2C $30 $17 $0F -> [0,10,12,7]
;     SP3 $2C $07 $17 $0F -> [0,4,12,7]
;   flash_bg
;     BG0 $0F $0F $0F $30 -> [0,1,2,3]
;     BG1 $0F $0F $0F $0F -> [0,4,5,6]
;     BG2 $0F $0F $0F $0F -> [0,7,8,9]
;     BG3 $0F $0F $0F $0F -> [0,7,10,11]
;     SP0 $0F $0F $0F $0F -> [0,0,0,0]
;     SP1 $0F $0F $0F $0F -> [0,0,0,0]
;     SP2 $0F $0F $0F $0F -> [0,0,0,0]
;     SP3 $0F $0F $0F $0F -> [0,0,0,0]
;   flash_sp
;     BG0 $0F $0F $0F $0F -> [0,1,2,3]
;     BG1 $0F $0F $0F $0F -> [0,4,5,6]
;     BG2 $0F $0F $0F $0F -> [0,7,8,9]
;     BG3 $0F $0F $0F $0F -> [0,7,10,11]
;     SP0 $0F $30 $30 $30 -> [0,12,12,12]
;     SP1 $0F $0F $0F $0F -> [0,0,0,0]
;     SP2 $0F $0F $0F $0F -> [0,0,0,0]
;     SP3 $0F $0F $0F $0F -> [0,0,0,0]

            mx    %00

palCurrent  dw    0                   ; PAL_* id of the palette on screen (0 = none yet)

; SetDefaultPalette
;
; Before the game uploads a palette: the swizzle tables are title's, and so is the layout of the colors
; shown until the game's palette is detected.
; Called by the game's InitPlayfield (NES_StartUp) and at start-up.
SetDefaultPalette
            ldy   #PAL_TITLE
            sty   palCurrent
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jmp   NES_SetPaletteMap

; ApplyPaletteChange
;
; The game's PRE_RENDER hook (jsl), on the GS task.  If the palette RAM changed (ppuPalDirty, set by the
; engine's palette write handler), identify the palette in it and switch to it, or show its changed
; colors in the current palette's layout (fades, color cycling, an unknown palette).  While the
; background is off, the game is rebuilding the screen: the old colors stay on whatever is left on it,
; and the new ones come with the new screen.
ApplyPaletteChange
            ldal  ppuPalDirty
            beq   :none
            ldal  _ppumask
            and   #NES_PPUMASK_BG
            beq   :none
            lda   #0
            stal  ppuPalDirty         ; (first, so a write from here on is seen next time)
            ldx   palCurrent
            jsr   DetectNESPalette    ; A = Y = palette id, 0 if none
            beq   :colors             ; not a known palette (e.g. a step of a fade)
            cmp   palCurrent
            beq   :colors
            ldx   palCurrent
            sty   palCurrent
            jsr   UpdatePalette       ; X = from, Y = to
            rtl
:colors     ldy   palCurrent
            beq   :none               ; no palette yet
            jsr   LoadPaletteColors
:none       rtl

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply

            jsr   LoadPaletteColors
            pla
            jsl   RefreshPPUAttributesL   ; (in the engine bank: ppu_entry.s)
            rts

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #12
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_TITLE_MATCH
            dw    PAL_DUCK_MATCH
            dw    PAL_CLAY_MATCH
            dw    PAL_FLASH_BG_MATCH
            dw    PAL_FLASH_SP_MATCH
PAL_TITLE_MATCH
            db    $2C,$27,$0F,$0F,$30,$30,$0F,$2A,$2A,$0F,$27,$27   ; BG0-BG3
            db    $0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F   ; SP0-SP3
PAL_DUCK_MATCH
            db    $07,$29,$0A,$30,$29,$0A,$0F,$29,$18,$0F,$30,$16   ; BG0-BG3
            db    $30,$FF,$FF,$30,$26,$FF,$30,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_CLAY_MATCH
            db    $29,$19,$09,$07,$29,$1A,$0F,$29,$10,$0F,$30,$16   ; BG0-BG3
            db    $30,$0F,$0F,$30,$16,$07,$30,$17,$0F,$07,$17,$0F   ; SP0-SP3
PAL_FLASH_BG_MATCH
            db    $0F,$0F,$30,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F   ; BG0-BG3
            db    $0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F   ; SP0-SP3
PAL_FLASH_SP_MATCH
            db    $0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F   ; BG0-BG3
            db    $30,$30,$30,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_TITLE_SUCC
            dw    PAL_DUCK_SUCC
            dw    PAL_CLAY_SUCC
            dw    PAL_FLASH_BG_SUCC
            dw    PAL_FLASH_SP_SUCC
PAL_NONE_SUCC
            dw    0
PAL_TITLE_SUCC
            dw    PAL_DUCK,PAL_CLAY,0
PAL_DUCK_SUCC
            dw    PAL_FLASH_BG,PAL_FLASH_SP,PAL_TITLE,0
PAL_CLAY_SUCC
            dw    PAL_FLASH_BG,PAL_FLASH_SP,PAL_TITLE,0
PAL_FLASH_BG_SUCC
            dw    PAL_DUCK,PAL_CLAY,0
PAL_FLASH_SP_SUCC
            dw    PAL_DUCK,PAL_CLAY,0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_TITLE_SWIZZLE
            dw    PAL_DUCK_SWIZZLE
            dw    PAL_CLAY_SWIZZLE
            dw    PAL_FLASH_BG_SWIZZLE
            dw    PAL_FLASH_SP_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_TITLE_SWIZZLE
            dw    ^PAL_DUCK_SWIZZLE
            dw    ^PAL_CLAY_SWIZZLE
            dw    ^PAL_FLASH_BG_SWIZZLE
            dw    ^PAL_FLASH_SP_SWIZZLE

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_TITLE_CELLS
            dw    PAL_DUCK_CELLS
            dw    PAL_CLAY_CELLS
            dw    PAL_FLASH_BG_CELLS
            dw    PAL_FLASH_SP_CELLS
PAL_TITLE_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_DUCK_CELLS
            db    $FF,$12,$10,$02,$FF,$14,$10,$02,$FF,$0E,$10,$FF,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$14,$04,$06,$FF,$14,$08,$0A,$FF,$14,$0C,$18,$FF,$1A,$1C,$1E   ; SP0-SP3
PAL_CLAY_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$14,$0E,$0E,$FF,$14,$16,$08,$FF,$14,$18,$0E,$FF,$08,$18,$0E   ; SP0-SP3
PAL_FLASH_BG_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_FLASH_SP_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$18,$18,$18,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3

; from id -> its row of to id -> background groups to redraw (bit 0 = BG0 .. bit 3 = BG3).
; From no palette (0), everything is redrawn.
BG_UPDATE_MASKS
            dw    BG_UPDATE_MASKS_NONE
            dw    BG_UPDATE_MASKS_TITLE
            dw    BG_UPDATE_MASKS_DUCK
            dw    BG_UPDATE_MASKS_CLAY
            dw    BG_UPDATE_MASKS_FLASH_BG
            dw    BG_UPDATE_MASKS_FLASH_SP
BG_UPDATE_MASKS_NONE
            dw    $0000,%1111,%1111,%1111,%1111,%1111
BG_UPDATE_MASKS_TITLE
            dw    $0000
            dw    %0000   ; to title
            dw    %0011   ; to duck
            dw    %0000   ; to clay
            dw    %0000   ; to flash_bg
            dw    %0000   ; to flash_sp
BG_UPDATE_MASKS_DUCK
            dw    $0000
            dw    %0011   ; to title
            dw    %0000   ; to duck
            dw    %0011   ; to clay
            dw    %0011   ; to flash_bg
            dw    %0011   ; to flash_sp
BG_UPDATE_MASKS_CLAY
            dw    $0000
            dw    %0000   ; to title
            dw    %0011   ; to duck
            dw    %0000   ; to clay
            dw    %0000   ; to flash_bg
            dw    %0000   ; to flash_sp
BG_UPDATE_MASKS_FLASH_BG
            dw    $0000
            dw    %0000   ; to title
            dw    %0011   ; to duck
            dw    %0000   ; to clay
            dw    %0000   ; to flash_bg
            dw    %0000   ; to flash_sp
BG_UPDATE_MASKS_FLASH_SP
            dw    $0000
            dw    %0000   ; to title
            dw    %0011   ; to duck
            dw    %0000   ; to clay
            dw    %0000   ; to flash_bg
            dw    %0000   ; to flash_sp
